INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine smarte Fabrik immer Roboter braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Vernetzung reicht"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept steht hinter der Vernetzung von Maschinen?', 3, '[{"text": "IoT", "correct": true, "because": "Internet of Things verbindet Geräte"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien treiben eine digitale Produktion voran?', 5, '[{"text": "Sensoren", "correct": true, "because": "Erfassen Daten"}, {"text": "Cloud Computing", "correct": true, "because": "Speichert und analysiert"}, {"text": "Big Data", "correct": true, "because": "Verarbeitet große Mengen"}, {"text": "Webdesign", "correct": false, "because": "Kein Produktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Vernetzung erhöht Effizienz. b) Es braucht immer neue Maschinen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bestehende Maschinen nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine intelligente Fabrik plane?', 4, '[{"text": "Datenintegration", "correct": false, "because": "Schlüssel für Vernetzung"}, {"text": "Sicherheit", "correct": false, "because": "Schützt Systeme"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alles automatisch läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Menschliche Steuerung nötig"}, {"text": "Ja", "correct": false, "because": "Teilautomatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für Maschinenkommunikation?', 3, '[{"text": "MQTT", "correct": true, "because": "Leichtgewichtig für IoT"}, {"text": "HTML", "correct": false, "because": "Webentwicklung"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine vernetzte Produktion?', 5, '[{"text": "Echtzeitdaten", "correct": true, "because": "Verbessert Entscheidungen"}, {"text": "Automatisierung", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Flexibilität", "correct": true, "because": "Passt Produktion an"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Sensoren Daten liefern und b) alles offline läuft. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vernetzung ist online"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine smarte Fertigung?', 4, '[{"text": "IoT-Geräte", "correct": false, "because": "Sammeln Daten"}, {"text": "Datenanalyse", "correct": false, "because": "Optimiert Prozesse"}, {"text": "Bürostühle", "correct": true, "because": "Kein Produktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine digitale Fabrik immer teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Umfang"}, {"text": "Ja", "correct": false, "because": "Kosteneffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielt die Cloud in der Produktion?', 4, '[{"text": "Datenverarbeitung", "correct": true, "because": "Analysiert Echtzeitdaten"}, {"text": "Speicherung", "correct": true, "because": "Sichert Informationen"}, {"text": "Webdesign", "correct": false, "because": "Kein Produktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es keine Sicherheitsrisiken gibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vernetzung erhöht Risiken"}, {"text": "Ja", "correct": false, "because": "Cybersecurity nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer vernetzten Fabrik?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Optimiert Prozesse"}, {"text": "Kostensteigerung", "correct": false, "because": "Nicht erwünscht"}, {"text": "Manuelle Arbeit", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenanalyse ist zentral. b) Es braucht keine IT-Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für Echtzeitdaten?', 4, '[{"text": "Edge Computing", "correct": true, "because": "Verarbeitet vor Ort"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Zu langsam"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob alte Maschinen integriert werden können?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Sensoren nachrüstbar"}, {"text": "Nein", "correct": false, "because": "Flexibel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Produktion intelligent?', 5, '[{"text": "Vernetzung", "correct": true, "because": "Maschinen kommunizieren"}, {"text": "Automatisierung", "correct": true, "because": "Reduziert Eingriffe"}, {"text": "Datenanalyse", "correct": true, "because": "Optimiert Abläufe"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Cybersecurity unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Schützt vernetzte Systeme"}, {"text": "Ja", "correct": false, "because": "Risiken hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer digitalen Fabrik?', 4, '[{"text": "Echtzeitüberwachung", "correct": true, "because": "Datenoptimierung"}, {"text": "Manuelle Fertigung", "correct": false, "because": "Gegenteil"}, {"text": "Webentwicklung", "correct": false, "because": "Anderer Bereich"}]');
